from fractions import Fraction

def constrained_square(target,lower,upper):
    values = (target,lower,upper)
    if any(type(v) not in (int,Fraction) or abs(v)>1000 for v in values):
        raise ValueError("expected bounded int/Fraction values, excluding bool")
    target,lower,upper = map(Fraction,values)
    if lower>upper:
        raise ValueError("empty interval")
    answer = min(upper,max(lower,target))
    return answer,(answer-target)**2,2*(answer-target)

for target in (3,-2,Fraction(1,2)):
    print(*(str(v) for v in constrained_square(target,0,1)))
print(constrained_square(3,1,1)[0])

from fractions import Fraction

def square_step(x,initial_step=1,max_attempts=12):
    if type(x) not in (int,Fraction) or abs(x)>1000:
        raise ValueError("expected bounded int/Fraction iterate")
    if type(initial_step) not in (int,Fraction) or not 0<initial_step<=1000:
        raise ValueError("expected bounded positive int/Fraction step")
    if type(max_attempts) is not int or not 1<=max_attempts<=100:
        raise ValueError("expected1..100attempts, excluding bool")
    x,step = Fraction(x),Fraction(initial_step)
    objective = (x-3)**2
    gradient = 2*(x-3)
    if gradient==0:
        return {"status":"stationary","x":x,"step":Fraction(0),"backtracks":0}
    direction = -gradient
    slope = gradient*direction
    for backtracks in range(max_attempts):
        candidate = x+step*direction
        # Armijo c=1/4, beta=1/2 on this exact fixed quadratic only.
        if (candidate-3)**2 <= objective+Fraction(1,4)*step*slope:
            return {"status":"accepted","x":candidate,"step":step,"backtracks":backtracks}
        step /= 2
    return {"status":"line-search-limit","x":x,"step":Fraction(0),"backtracks":max_attempts}

for kwargs in ({"x":0},{"x":3},{"x":0,"max_attempts":1}):
    result = square_step(**kwargs)
    print(result["status"],str(result["x"]),str(result["step"]),result["backtracks"])
